179:     public:
180:         ANSIColourImpl( IStream* stream ): ColourImpl( stream ) {}
181: 
182:         static bool useImplementationForStream(IStream const& stream) {
183:             // This is kinda messy due to trying to support a bunch of
184:             // different platforms at once.
185:             // The basic idea is that if we are asked to do autodetection (as
186:             // opposed to being told to use posixy colours outright), then we
187:             // only want to use the colours if we are writing to console.
188:             // However, console might be redirected, so we make an attempt at
189:             // checking for that on platforms where we know how to do that.
190:             bool useColour = stream.isConsole();
191: #if defined( CATCH_INTERNAL_HAS_ISATTY ) && \
192:     !( defined( __DJGPP__ ) && defined( __STRICT_ANSI__ ) )
193:             ErrnoGuard _; // for isatty
194:             useColour = useColour && isatty( STDOUT_FILENO );
195: #    endif
196: #    if defined( CATCH_PLATFORM_MAC ) || defined( CATCH_PLATFORM_IPHONE )
197:             useColour = useColour && !isDebuggerActive();
198: #    endif
199: 
200:             return useColour;
201:         }
202: 
203:     private:
204:         void use( Colour::Code _colourCode ) const override {
205:             auto setColour = [&out =
206:                                   m_stream->stream()]( char const* escapeCode ) {
207:                 // The escape sequence must be flushed to console, otherwise
208:                 // if stdin and stderr are intermixed, we'd get accidentally
209:                 // coloured output.
210:                 out << '\033' << escapeCode << std::flush;
211:             };
212:             switch( _colourCode ) {
213:                 case Colour::None:
214:                 case Colour::White:     return setColour( "[0m" );
215:                 case Colour::Red:       return setColour( "[0;31m" );
216:                 case Colour::Green:     return setColour( "[0;32m" );
217:                 case Colour::Blue:      return setColour( "[0;34m" );
218:                 case Colour::Cyan:      return setColour( "[0;36m" );
219:                 case Colour::Yellow:    return setColour( "[0;33m" );
220:                 case Colour::Grey:      return setColour( "[1;30m" );
221: 
222:                 case Colour::LightGrey:     return setColour( "[0;37m" );
223:                 case Colour::BrightRed:     return setColour( "[1;31m" );
224:                 case Colour::BrightGreen:   return setColour( "[1;32m" );
225:                 case Colour::BrightWhite:   return setColour( "[1;37m" );
226:                 case Colour::BrightYellow:  return setColour( "[1;33m" );
227: 
228:                 case Colour::Bright: CATCH_INTERNAL_ERROR( "not a colour" );
229:                 default: CATCH_INTERNAL_ERROR( "Unknown colour requested" );
230:             }
231:         }
