9: /** \file
10:  * This file provides platform specific implementations of FatalConditionHandler
11:  *
12:  * This means that there is a lot of conditional compilation, and platform
13:  * specific code. Currently, Catch2 supports a dummy handler (if no
14:  * handler is desired), and 2 platform specific handlers:
15:  *  * Windows' SEH
16:  *  * POSIX signals
17:  *
18:  * Consequently, various pieces of code below are compiled if either of
19:  * the platform specific handlers is enabled, or if none of them are
20:  * enabled. It is assumed that both cannot be enabled at the same time,
21:  * and doing so should cause a compilation error.
22:  *
23:  * If another platform specific handler is added, the compile guards
24:  * below will need to be updated taking these assumptions into account.
25:  */
26: 
27: #include <catch2/internal/catch_fatal_condition_handler.hpp>
28: 
29: #include <catch2/internal/catch_compiler_capabilities.hpp>
30: #include <catch2/internal/catch_context.hpp>
31: #include <catch2/internal/catch_enforce.hpp>
32: #include <catch2/interfaces/catch_interfaces_capture.hpp>
33: #include <catch2/internal/catch_windows_h_proxy.hpp>
34: #include <catch2/internal/catch_stdstreams.hpp>
35: 
36: #include <algorithm>
37: 
38: #if !defined( CATCH_CONFIG_WINDOWS_SEH ) && !defined( CATCH_CONFIG_POSIX_SIGNALS )
39: 
40: namespace Catch {
41: 
42:     // If neither SEH nor signal handling is required, the handler impls
43:     // do not have to do anything, and can be empty.
44:     void FatalConditionHandler::engage_platform() {}
45:     void FatalConditionHandler::disengage_platform() noexcept {}
46:     FatalConditionHandler::FatalConditionHandler() = default;
47:     FatalConditionHandler::~FatalConditionHandler() = default;
48: 
49: } // end namespace Catch
50: 
51: #endif // !CATCH_CONFIG_WINDOWS_SEH && !CATCH_CONFIG_POSIX_SIGNALS
52: 
53: #if defined( CATCH_CONFIG_WINDOWS_SEH ) && defined( CATCH_CONFIG_POSIX_SIGNALS )
54: #error "Inconsistent configuration: Windows' SEH handling and POSIX signals cannot be enabled at the same time"
55: #endif // CATCH_CONFIG_WINDOWS_SEH && CATCH_CONFIG_POSIX_SIGNALS
56: 
57: #if defined( CATCH_CONFIG_WINDOWS_SEH ) || defined( CATCH_CONFIG_POSIX_SIGNALS )
58: 
59: namespace {
60:     //! Signals fatal error message to the run context
61:     void reportFatal( char const * const message ) {
62:         Catch::getCurrentContext().getResultCapture()->handleFatalErrorCondition( message );
63:     }
64: 
65:     //! Minimal size Catch2 needs for its own fatal error handling.
66:     //! Picked empirically, so it might not be sufficient on all
67:     //! platforms, and for all configurations.
68:     constexpr std::size_t minStackSizeForErrors = 32 * 1024;
69: } // end unnamed namespace
70: 
71: #endif // CATCH_CONFIG_WINDOWS_SEH || CATCH_CONFIG_POSIX_SIGNALS
72: 
73: #if defined( CATCH_CONFIG_WINDOWS_SEH )
74: 
75: namespace Catch {
76: 
77:     struct SignalDefs { DWORD id; const char* name; };
78: 
79:     // There is no 1-1 mapping between signals and windows exceptions.
80:     // Windows can easily distinguish between SO and SigSegV,
81:     // but SigInt, SigTerm, etc are handled differently.
82:     static constexpr SignalDefs signalDefs[] = {
83:         { EXCEPTION_ILLEGAL_INSTRUCTION,  "SIGILL - Illegal instruction signal" },
84:         { EXCEPTION_STACK_OVERFLOW, "SIGSEGV - Stack overflow" },
85:         { EXCEPTION_ACCESS_VIOLATION, "SIGSEGV - Segmentation violation signal" },
86:         { EXCEPTION_INT_DIVIDE_BY_ZERO, "Divide by zero error" },
87:     };
88: 
89:     // Since we do not support multiple instantiations, we put these
90:     // into global variables and rely on cleaning them up in outlined
91:     // constructors/destructors
92:     static LPTOP_LEVEL_EXCEPTION_FILTER previousTopLevelExceptionFilter = nullptr;
93: 
94: 
95:     static LONG CALLBACK topLevelExceptionFilter(PEXCEPTION_POINTERS ExceptionInfo) {
96:         for (auto const& def : signalDefs) {
97:             if (ExceptionInfo->ExceptionRecord->ExceptionCode == def.id) {
98:                 reportFatal(def.name);
99:             }
100:         }
101:         // If a filter was previously registered, invoke it
102:         if (previousTopLevelExceptionFilter) {
103:             return previousTopLevelExceptionFilter(ExceptionInfo);
104:         }
105:         // Otherwise, pass along all exceptions.
106:         // This stops us from eating debugger breaks etc.
107:         return EXCEPTION_CONTINUE_SEARCH;
108:     }
109: 
110:     // For MSVC, we reserve part of the stack memory for handling
111:     // memory overflow structured exception.
112:     FatalConditionHandler::FatalConditionHandler() {
113:         ULONG guaranteeSize = static_cast<ULONG>(minStackSizeForErrors);
114:         if (!SetThreadStackGuarantee(&guaranteeSize)) {
115:             // We do not want to fully error out, because needing
116:             // the stack reserve should be rare enough anyway.
117:             Catch::cerr()
118:                 << "Failed to reserve piece of stack."
119:                 << " Stack overflows will not be reported successfully.";
120:         }
121:     }
122: 
123:     // We do not attempt to unset the stack guarantee, because
124:     // Windows does not support lowering the stack size guarantee.
125:     FatalConditionHandler::~FatalConditionHandler() = default;
126: 
127: 
128:     void FatalConditionHandler::engage_platform() {
129:         // Register as a the top level exception filter.
130:         previousTopLevelExceptionFilter = SetUnhandledExceptionFilter(topLevelExceptionFilter);
131:     }
132: 
133:     void FatalConditionHandler::disengage_platform() noexcept {
134:         if (SetUnhandledExceptionFilter(previousTopLevelExceptionFilter) != topLevelExceptionFilter) {
135:             Catch::cerr()
136:                 << "Unexpected SEH unhandled exception filter on disengage."
137:                 << " The filter was restored, but might be rolled back unexpectedly.";
138:         }
139:         previousTopLevelExceptionFilter = nullptr;
140:     }
141: 
142: } // end namespace Catch
143: 
144: #endif // CATCH_CONFIG_WINDOWS_SEH
145: 
146: #if defined( CATCH_CONFIG_POSIX_SIGNALS )
147: 
148: #include <signal.h>
149: 
150: namespace Catch {
151: 
152:     struct SignalDefs {
153:         int id;
154:         const char* name;
155:     };
156: 
157:     static constexpr SignalDefs signalDefs[] = {
158:         { SIGINT,  "SIGINT - Terminal interrupt signal" },
159:         { SIGILL,  "SIGILL - Illegal instruction signal" },
160:         { SIGFPE,  "SIGFPE - Floating point error signal" },
161:         { SIGSEGV, "SIGSEGV - Segmentation violation signal" },
162:         { SIGTERM, "SIGTERM - Termination request signal" },
163:         { SIGABRT, "SIGABRT - Abort (abnormal termination) signal" }
164:     };
165: 
166: // Older GCCs trigger -Wmissing-field-initializers for T foo = {}
167: // which is zero initialization, but not explicit. We want to avoid
168: // that.
169: #if defined(__GNUC__)
170: #    pragma GCC diagnostic push
171: #    pragma GCC diagnostic ignored "-Wmissing-field-initializers"
172: #endif
173: 
174:     static char* altStackMem = nullptr;
175:     static std::size_t altStackSize = 0;
176:     static stack_t oldSigStack{};
177:     static struct sigaction oldSigActions[sizeof(signalDefs) / sizeof(SignalDefs)]{};
178: 
179:     static void restorePreviousSignalHandlers() noexcept {
180:         // We set signal handlers back to the previous ones. Hopefully
181:         // nobody overwrote them in the meantime, and doesn't expect
182:         // their signal handlers to live past ours given that they
183:         // installed them after ours..
184:         for (std::size_t i = 0; i < sizeof(signalDefs) / sizeof(SignalDefs); ++i) {
185:             sigaction(signalDefs[i].id, &oldSigActions[i], nullptr);
186:         }
187:         // Return the old stack
188:         sigaltstack(&oldSigStack, nullptr);
189:     }
190: 
191:     static void handleSignal( int sig ) {
192:         char const * name = "<unknown signal>";
193:         for (auto const& def : signalDefs) {
194:             if (sig == def.id) {
195:                 name = def.name;
196:                 break;
197:             }
198:         }
199:         // We need to restore previous signal handlers and let them do
200:         // their thing, so that the users can have the debugger break
201:         // when a signal is raised, and so on.
202:         restorePreviousSignalHandlers();
203:         reportFatal( name );
204:         raise( sig );
205:     }
206: 
207:     FatalConditionHandler::FatalConditionHandler() {
208:         assert(!altStackMem && "Cannot initialize POSIX signal handler when one already exists");
209:         if (altStackSize == 0) {
210:             altStackSize = std::max(static_cast<size_t>(SIGSTKSZ), minStackSizeForErrors);
211:         }
212:         altStackMem = new char[altStackSize]();
213:     }
214: 
215:     FatalConditionHandler::~FatalConditionHandler() {
216:         delete[] altStackMem;
217:         // We signal that another instance can be constructed by zeroing
218:         // out the pointer.
219:         altStackMem = nullptr;
220:     }
221: 
222:     void FatalConditionHandler::engage_platform() {
223:         stack_t sigStack;
224:         sigStack.ss_sp = altStackMem;
225:         sigStack.ss_size = altStackSize;
226:         sigStack.ss_flags = 0;
227:         sigaltstack(&sigStack, &oldSigStack);
228:         struct sigaction sa = { };
229: 
230:         sa.sa_handler = handleSignal;
231:         sa.sa_flags = SA_ONSTACK;
232:         for (std::size_t i = 0; i < sizeof(signalDefs)/sizeof(SignalDefs); ++i) {
233:             sigaction(signalDefs[i].id, &sa, &oldSigActions[i]);
234:         }
235:     }
236: 
237: #if defined(__GNUC__)
238: #    pragma GCC diagnostic pop
239: #endif
240: 
241: 
242:     void FatalConditionHandler::disengage_platform() noexcept {
243:         restorePreviousSignalHandlers();
244:     }
245: 
246: } // end namespace Catch
247: 
248: #endif // CATCH_CONFIG_POSIX_SIGNALS

