34:         //! A no-op implementation, used if no reporter wants output
35:         //! redirection.
36:         class NoopRedirect final : public OutputRedirect {
37:             void activateImpl() override {}
38:             void deactivateImpl() override {}
39:             std::string getStdout() override { return {}; }
40:             std::string getStderr() override { return {}; }
