44:         /**
45:          * Redirects specific stream's rdbuf with another's.
46:          *
47:          * Redirection can be stopped and started on-demand, assumes
48:          * that the underlying stream's rdbuf aren't changed by other
49:          * users.
50:          */
51:         class RedirectedStreamNew {
52:             std::ostream& m_originalStream;
53:             std::ostream& m_redirectionStream;
54:             std::streambuf* m_prevBuf;
55: 
56:         public:
57:             RedirectedStreamNew( std::ostream& originalStream,
58:                                  std::ostream& redirectionStream ):
59:                 m_originalStream( originalStream ),
60:                 m_redirectionStream( redirectionStream ),
61:                 m_prevBuf( m_originalStream.rdbuf() ) {}
62: 
63:             void startRedirect() {
64:                 m_originalStream.rdbuf( m_redirectionStream.rdbuf() );
65:             }
66:             void stopRedirect() { m_originalStream.rdbuf( m_prevBuf ); }
67:         };
68: 
69:         /**
70:          * Redirects the `std::cout`, `std::cerr`, `std::clog` streams,
71:          * but does not touch the actual `stdout`/`stderr` file descriptors.
72:          */
73:         class StreamRedirect final : public OutputRedirect {
74:             ReusableStringStream m_redirectedOut, m_redirectedErr;
75:             RedirectedStreamNew m_cout, m_cerr, m_clog;
76: 
77:         public:
78:             StreamRedirect():
79:                 m_cout( Catch::cout(), m_redirectedOut.get() ),
80:                 m_cerr( Catch::cerr(), m_redirectedErr.get() ),
81:                 m_clog( Catch::clog(), m_redirectedErr.get() ) {}
82: 
83:             void activateImpl() override {
84:                 m_cout.startRedirect();
85:                 m_cerr.startRedirect();
86:                 m_clog.startRedirect();
87:             }
88:             void deactivateImpl() override {
89:                 m_cout.stopRedirect();
90:                 m_cerr.stopRedirect();
91:                 m_clog.stopRedirect();
92:             }
93:             std::string getStdout() override { return m_redirectedOut.str(); }
94:             std::string getStderr() override { return m_redirectedErr.str(); }
95:             void clearBuffers() override {
96:                 m_redirectedOut.str( "" );
97:                 m_redirectedErr.str( "" );
98:             }
99:         };
