99:     Config::Config( ConfigData const& data ):
100:         m_data( data ) {
101:         // We need to trim filter specs to avoid trouble with superfluous
102:         // whitespace (esp. important for bdd macros, as those are manually
103:         // aligned with whitespace).
104: 
105:         for (auto& elem : m_data.testsOrTags) {
106:             elem = trim(elem);
107:         }
108: 
109:         // Insert the default reporter if user hasn't asked for a specific one
110:         if ( m_data.reporterSpecifications.empty() ) {
111: #if defined( CATCH_CONFIG_DEFAULT_REPORTER )
112:             const auto default_spec = CATCH_CONFIG_DEFAULT_REPORTER;
113: #else
114:             const auto default_spec = "console";
115: #endif
116:             auto parsed = parseReporterSpec(default_spec);
117:             CATCH_ENFORCE( parsed,
118:                            "Cannot parse the provided default reporter spec: '"
119:                                << default_spec << '\'' );
120:             m_data.reporterSpecifications.push_back( std::move( *parsed ) );
121:         }
122: 
123:         // Reading bazel env vars can change some parts of the config data,
124:         // so we have to process the bazel env before acting on the config.
125:         if ( enableBazelEnvSupport() ) {
126:             readBazelEnvVars();
127:         }
128: 
129:         // Bazel support can modify the test specs, so parsing has to happen
130:         // after reading Bazel env vars.
131:         TestSpecParser parser( ITagAliasRegistry::get() );
132:         if ( !m_data.testsOrTags.empty() ) {
133:             m_hasTestFilters = true;
134:             for ( auto const& testOrTags : m_data.testsOrTags ) {
135:                 parser.parse( testOrTags );
136:             }
137:         }
138:         m_testSpec = parser.testSpec();
139: 
140: 
141:         // We now fixup the reporter specs to handle default output spec,
142:         // default colour spec, etc
143:         bool defaultOutputUsed = false;
144:         for ( auto const& reporterSpec : m_data.reporterSpecifications ) {
145:             // We do the default-output check separately, while always
146:             // using the default output below to make the code simpler
147:             // and avoid superfluous copies.
148:             if ( reporterSpec.outputFile().none() ) {
149:                 CATCH_ENFORCE( !defaultOutputUsed,
150:                                "Internal error: cannot use default output for "
151:                                "multiple reporters" );
152:                 defaultOutputUsed = true;
153:             }
154: 
155:             m_processedReporterSpecs.push_back( ProcessedReporterSpec{
156:                 reporterSpec.name(),
157:                 reporterSpec.outputFile() ? *reporterSpec.outputFile()
158:                                           : data.defaultOutputFilename,
159:                 reporterSpec.colourMode().valueOr( data.defaultColourMode ),
160:                 reporterSpec.customOptions() } );
161:         }
162:     }
