225:     void Config::readBazelEnvVars() {
226:         // Register a JUnit reporter for Bazel. Bazel sets an environment
227:         // variable with the path to XML output. If this file is written to
228:         // during test, Bazel will not generate a default XML output.
229:         // This allows the XML output file to contain higher level of detail
230:         // than what is possible otherwise.
231:         const auto bazelOutputFile = Detail::getEnv( "XML_OUTPUT_FILE" );
232: 
233:         if ( bazelOutputFile ) {
234:             m_data.reporterSpecifications.push_back(
235:                 { "junit", std::string( bazelOutputFile ), {}, {} } );
236:         }
237: 
238:         const auto bazelTestSpec = Detail::getEnv( "TESTBRIDGE_TEST_ONLY" );
239:         if ( bazelTestSpec ) {
240:             // Presumably the test spec from environment should overwrite
241:             // the one we got from CLI (if we got any)
242:             m_data.testsOrTags.clear();
243:             m_data.testsOrTags.push_back( bazelTestSpec );
244:         }
245: 
246:         const auto bazelShardOptions = readBazelShardingOptions();
247:         if ( bazelShardOptions ) {
248:             std::ofstream f( bazelShardOptions->shardFilePath,
249:                              std::ios_base::out | std::ios_base::trunc );
250:             if ( f.is_open() ) {
251:                 f << "";
252:                 m_data.shardIndex = bazelShardOptions->shardIndex;
253:                 m_data.shardCount = bazelShardOptions->shardCount;
254:             }
255:         }
256: 
257:         const auto bazelExitGuardFile = Detail::getEnv( "TEST_PREMATURE_EXIT_FILE" );
258:         if (bazelExitGuardFile) {
259:             m_data.prematureExitGuardFilePath = bazelExitGuardFile;
260:         }
261: 
262:         const auto bazelRandomSeed = Detail::getEnv( "TEST_RANDOM_SEED" );
263:         if ( bazelRandomSeed ) {
264:             auto parsedSeed = parseUInt( bazelRandomSeed, 0 );
265:             if ( !parsedSeed ) {
266:                 // Currently we handle issues with parsing other Bazel Env
267:                 // options by warning and ignoring the issue. So we do the
268:                 // same for random seed option.
269:                 Catch::cerr()
270:                     << "Warning: could not parse 'TEST_RANDOM_SEED' ('"
271:                     << bazelRandomSeed << "') as proper seed.\n";
272:             } else {
273:                 m_data.rngSeed = *parsedSeed;
274:             }
