53:             constexpr auto clock_cost_estimation_tick_limit = 100000;
54:             constexpr auto clock_cost_estimation_time = std::chrono::milliseconds(10);
55:             constexpr auto clock_cost_estimation_iterations = 10000;
56: 
57:             template <typename Clock>
58:             int warmup() {
59:                 return run_for_at_least<Clock>(warmup_time, warmup_seed, &resolution<Clock>)
60:                     .iterations;
61:             }
62:             template <typename Clock>
63:             EnvironmentEstimate estimate_clock_resolution(int iterations) {
64:                 auto r = run_for_at_least<Clock>(clock_resolution_estimation_time, iterations, &resolution<Clock>)
65:                     .result;
66:                 return {
67:                     FDuration(mean(r.data(), r.data() + r.size())),
68:                     classify_outliers(r.data(), r.data() + r.size()),
69:                 };
