24:         template<typename WriterF, std::size_t bufferSize=256>
25:         class StreamBufImpl final : public std::streambuf {
26:             char data[bufferSize];
27:             WriterF m_writer;
28: 
29:         public:
30:             StreamBufImpl() {
31:                 setp( data, data + sizeof(data) );
32:             }
33: 
34:             ~StreamBufImpl() noexcept override {
35:                 StreamBufImpl::sync();
36:             }
37: 
38:         private:
39:             int overflow( int c ) override {
40:                 sync();
41: 
42:                 if( c != EOF ) {
43:                     if( pbase() == epptr() )
44:                         m_writer( std::string( 1, static_cast<char>( c ) ) );
45:                     else
46:                         sputc( static_cast<char>( c ) );
47:                 }
48:                 return 0;
49:             }
50: 
51:             int sync() override {
52:                 if( pbase() != pptr() ) {
53:                     m_writer( std::string( pbase(), static_cast<std::string::size_type>( pptr() - pbase() ) ) );
54:                     setp( pbase(), epptr() );
55:                 }
56:                 return 0;
57:             }
58:         };
